files.content:
:root{--a:#1c5fa6;--a2:#8fc3f5;--a3:#ffc857;--plate:#0b2547;--rail-d:#0b1624;--card-d:#14304f}
@font-face{font-family:Tajawal;font-weight:400;src:url(fonts/tajawal-400.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:500;src:url(fonts/tajawal-500.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:700;src:url(fonts/tajawal-700.woff2) format("woff2");font-display:swap}
:root{--bg:#f1f3f2;--panel:#fff;--ink:#17201e;--muted:#5d6b68;--line:#d8dfdc;--soft:#e8eeec;--on:#fff;--bad:#b3342b;--warn:#a8741a;--ok:#2d7a52}
html[data-theme=dark]{--bg:#111716;--panel:#192120;--ink:#e9efed;--muted:#9eaeaa;--line:#2b3735;--soft:#212b29;--on:#08201f;--bad:#ff8c80;--warn:#e6b34f;--ok:#6fcf9b}
*{box-sizing:border-box}html,body{margin:0;background:var(--bg);color:var(--ink)}
body{font:400 15px/1.65 Tajawal,system-ui,sans-serif;-webkit-text-size-adjust:100%;font-variant-numeric:tabular-nums}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer;background:none;border:0;padding:0;text-align:inherit}a{color:var(--a)}
:focus-visible{outline:3px solid var(--a2);outline-offset:2px;border-radius:6px}
.ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}.ic.mini{width:13px;height:13px;margin-inline-start:6px;vertical-align:-1px;color:var(--muted)}
small{font-size:12.5px;color:var(--muted)}.grow{flex:1}.muted{color:var(--muted)}h1,h2,h3{margin:0;line-height:1.3}
#shell{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:100vh}
#rail{background:var(--a);color:#fff;display:flex;flex-direction:column;gap:18px;padding:22px 14px;position:sticky;top:0;height:100vh}
html[data-theme=dark] #rail{background:var(--rail-d,#0c1514);border-inline-end:1px solid var(--line)}
.brand{display:grid;gap:3px;padding:6px 8px 16px;border-bottom:1px solid #ffffff2a}.brand .av{margin-bottom:8px}.brand strong{font-size:18px}.brand small{color:#ffffffb8}
.rail-nav{display:grid;gap:4px}#rail button{display:flex;gap:12px;align-items:center;padding:10px 12px;border-radius:9px;color:#ffffffd0}#rail button:hover{background:#ffffff18}
#rail button.cur{background:#ffffff26;color:#fff;font-weight:700;box-shadow:inset -3px 0 var(--a3)}
#col{min-width:0}#top{display:none}#tabs{display:none}
#view{max-width:920px;margin:0 auto;padding:24px 28px 56px;outline:0}
.av{width:var(--s);height:var(--s);border-radius:50%;background:var(--a2);color:var(--plate);display:grid;place-items:center;overflow:hidden;flex:none;border:2px solid #ffffff55;font-weight:700;font-size:calc(var(--s) * .42)}.av img{width:100%;height:100%;object-fit:cover}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--panel);font-weight:500}
.btn.pri{background:var(--a);border-color:var(--a);color:#fff}html[data-theme=dark] .btn.pri{background:var(--a2);border-color:var(--a2);color:var(--plate)}
.btn.quiet{background:transparent}.btn.danger{color:var(--bad);border-color:var(--bad);background:transparent}.btn.small{min-height:34px;padding:4px 12px;font-size:14px}.btn:disabled{opacity:.5}
.icon{display:inline-grid;place-items:center;width:42px;height:42px;border-radius:10px}.icon:hover{background:var(--soft)}.icon.s{width:38px;height:38px;color:var(--muted)}
/* بطاقة الهوية: العنصر المميز */
.card-id{display:flex;gap:18px;align-items:center;background:var(--a);color:#fff;border-radius:18px;padding:22px 24px;position:relative;overflow:hidden}
.card-id::after{content:"";position:absolute;inset-inline-end:-40px;top:-40px;width:170px;height:170px;border-radius:50%;background:var(--a3);opacity:.22}
html[data-theme=dark] .card-id{background:var(--card-d,#16302e)}
.card-id .av{border-color:#fff8;--plate:#fff}.card-id h1{font-size:23px}.card-id p{margin:2px 0 8px;opacity:.88}.ci-t{min-width:0;position:relative;z-index:1}
.qas{display:flex;gap:8px;flex-wrap:wrap}.qa{display:inline-flex;gap:6px;align-items:center;background:#ffffff26;color:#fff;border-radius:99px;padding:5px 14px;font-size:14px;text-decoration:none;font-weight:500}.qa:hover{background:#ffffff3a}
.panel .qa,.sheet .qa{background:var(--soft);color:var(--ink)}
.bio{margin:14px 2px;white-space:pre-wrap}
.stats{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px;margin:16px 0}
.stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px 14px;display:grid}.stat b{font-size:26px;line-height:1.1}.stat.hot{border-color:var(--bad)}.stat.hot b{color:var(--bad)}.stat:hover{border-color:var(--a2)}
.ledger{display:grid;grid-template-columns:repeat(3,1fr);background:var(--panel);border:1px solid var(--line);border-radius:12px;margin:8px 0}.ledger>div{padding:12px 16px;display:grid}.ledger>div+div{border-inline-start:1px solid var(--line)}.ledger b{font-size:22px}.ledger .owed b{color:var(--bad)}
.calm{color:var(--muted);margin:10px 2px}.calm.sm{font-size:14px}.foot-note{margin-top:26px}
.sec-h{display:flex;justify-content:space-between;align-items:center;margin:24px 0 10px;gap:10px}.sec-h h3{font-size:16px;display:flex;gap:8px;align-items:center}.sec-h .ic{color:var(--a2)}
.tipl{display:grid;gap:8px}.tip{display:grid;background:var(--panel);border:1px solid var(--line);border-inline-start:5px solid var(--a2);border-radius:10px;padding:10px 14px}.tip.warn{border-inline-start-color:var(--warn)}.tip.bad{border-inline-start-color:var(--bad)}.tip strong{font-weight:500}
.list{display:grid;background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}
.row{display:flex;align-items:center;gap:6px;border-bottom:1px solid var(--line);min-height:58px;padding-inline-end:4px}.row:last-child{border-bottom:0}.row.dim{opacity:.55}
.rb{flex:1;min-width:0;display:flex;align-items:center;gap:12px;padding:10px 14px;text-align:start;width:100%}button.rb:hover,.row:hover{background:var(--soft)}
.row>.main,.rb>.main{flex:1;min-width:0;display:grid}.main strong{font-weight:500;overflow:hidden;text-overflow:ellipsis}.main small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.row>.main{padding:8px 14px}
.th{width:46px;height:46px;border-radius:10px;background:var(--soft);display:grid;place-items:center;overflow:hidden;flex:none;color:var(--a);font-weight:700}.th img{width:100%;height:100%;object-fit:cover}.th.sm{width:36px;height:36px}.th.big{width:100%;height:auto;aspect-ratio:4/3}
.when{width:62px;display:grid;text-align:center;flex:none;white-space:nowrap}.rank{width:30px;height:30px;border-radius:50%;background:var(--a2);color:var(--plate);display:grid;place-items:center;font-weight:700;margin-inline-start:12px}
.amt{color:var(--a);font-weight:700;white-space:nowrap}html[data-theme=dark] .amt{color:var(--a2)}
.tag{font-size:12.5px;padding:2px 10px;border-radius:99px;background:var(--soft);white-space:nowrap}.tag.bad{background:var(--bad);color:#fff}html[data-theme=dark] .tag.bad{color:#1a0a08}
.st{font-size:12.5px;padding:2px 10px;border-radius:99px;background:var(--soft);white-space:nowrap}.st-0{background:#e8eef9;color:#26467a}.st-1{background:#e1f3e8;color:#1f6b43}.st-2{background:#efe9f8;color:#5a3a86}.st-3{background:#f6e3e1;color:#8a2b24}
html[data-theme=dark] .st-0{background:#223250;color:#a9c4f2}html[data-theme=dark] .st-1{background:#1c3b2a;color:#9de0bb}html[data-theme=dark] .st-2{background:#33284a;color:#cdb6f2}html[data-theme=dark] .st-3{background:#4a2421;color:#f5b3ac}
.bar{display:flex;gap:8px;margin-bottom:10px}.search{flex:1;display:flex;align-items:center;gap:8px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:0 12px;color:var(--muted)}
.search input{flex:1;border:0;background:none;padding:10px 0;outline:0;min-width:0;color:var(--ink)}.search:focus-within{outline:3px solid var(--a2)}
.chips{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px;scrollbar-width:none}.chip{padding:6px 14px;border-radius:99px;border:1px solid var(--line);background:var(--panel);white-space:nowrap;font-size:14px}.chip i,.seg i{font-style:normal;font-size:11.5px;opacity:.75;margin-inline-start:6px;background:#0001;border-radius:99px;padding:0 6px}.chip.on{background:var(--a);color:#fff;border-color:var(--a)}html[data-theme=dark] .chip.on{background:var(--a2);color:var(--plate);border-color:var(--a2)}
.seg{display:flex;gap:4px;background:var(--soft);padding:4px;border-radius:12px;margin-bottom:12px;overflow-x:auto;scrollbar-width:none}.seg button{flex:1;padding:8px 14px;border-radius:9px;white-space:nowrap;text-align:center}.seg button.on{background:var(--panel);font-weight:700;box-shadow:0 1px 3px #0002}
.empty{text-align:center;padding:44px 16px;display:grid;justify-items:center;gap:6px}.empty .mark{width:66px;height:66px;border-radius:50%;background:var(--soft);display:grid;place-items:center;color:var(--a)}.empty .mark .ic{width:30px;height:30px}.empty p{margin:0 0 10px;color:var(--muted);max-width:36ch}
.facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));margin:12px 0;background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}.facts>div{padding:10px 14px;border-bottom:1px solid var(--line);border-inline-end:1px solid var(--line)}.facts dt{font-size:12.5px;color:var(--muted)}.facts dd{margin:0;font-weight:500;white-space:pre-wrap}
.gal{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px;margin-bottom:10px}.gi{display:block;border-radius:10px;overflow:hidden}
.zoom{position:fixed;inset:0;background:#000d;z-index:60;display:grid;place-items:center;padding:12px}.zoom img{max-width:100%;max-height:100%;border-radius:8px}
.phe{display:flex;gap:8px;flex-wrap:wrap}.pe{position:relative;width:76px;height:76px;border-radius:10px;overflow:hidden;background:var(--soft);display:grid;place-items:center}.pe .th{width:100%;height:100%;border-radius:0}.pe .x{position:absolute;top:3px;inset-inline-end:3px;background:#000a;color:#fff;border-radius:50%;width:22px;height:22px;display:grid;place-items:center}.pe .x .ic{width:12px;height:12px}
.pe.add{border:2px dashed var(--line);background:none;color:var(--muted);display:grid;align-content:center;justify-items:center;gap:0}
.bk-h{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px}.meterb{height:7px;background:var(--soft);border-radius:9px;overflow:hidden;margin:8px 0}.meterb i{display:block;height:100%;background:var(--a2)}.meterb i.hot{background:var(--bad)}
.reader{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;line-height:2;margin:10px 0;max-height:50vh;overflow:auto}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.foot{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.store{margin-top:12px}.note{color:var(--muted);font-size:13.5px;background:var(--soft);padding:9px 12px;border-radius:8px;margin:8px 0}
.splash-set{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;display:grid;gap:10px}.sw{display:flex;gap:10px;align-items:center}.sw input{width:20px;height:20px;accent-color:var(--a)}.splash-set select{background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:8px}
.splash{position:fixed;inset:0;z-index:90;background:var(--a);display:grid;place-items:center;transition:opacity .5s}.splash img{max-width:100%;max-height:100%;object-fit:contain}.splash.out{opacity:0}.skip{position:absolute;top:14px;inset-inline-end:14px;background:#0008;color:#fff;border-radius:99px;padding:5px 14px}
.lockscr{position:fixed;inset:0;z-index:95;background:var(--bg);display:grid;place-items:center;padding:20px}.gate{display:grid;gap:12px;justify-items:center;width:min(340px,100%);text-align:center}.gate .av{--plate:#fff}.gate input{width:100%;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px;text-align:center;font-size:17px}.err{color:var(--bad);margin:0;min-height:1.4em}
.veil{position:fixed;inset:0;background:#05090acc;z-index:30}.sheet{position:fixed;z-index:31;inset-block:0;inset-inline-start:0;width:min(470px,100%);background:var(--bg);display:flex;flex-direction:column;box-shadow:0 0 40px #0008}.sheet.wide{width:min(640px,100%)}
.sheet>header{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:var(--panel);border-bottom:1px solid var(--line)}.sheet h2{font-size:18px}.sheet-body{padding:16px;overflow:auto;flex:1}
.frm{display:flex;flex-wrap:wrap;gap:12px}.fld{display:grid;gap:5px;flex:1 1 100%}.fld.half{flex:1 1 calc(50% - 6px)}.fld>span{font-size:13.5px;color:var(--muted)}
.fld input,.fld select,.fld textarea{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;min-height:44px;width:100%;resize:vertical}.bad{border-color:var(--bad)!important}
.actions{flex:1 1 100%;display:flex;gap:8px;align-items:center;margin-top:8px}.sheet-body>.actions{margin-top:14px}.live{flex:1 1 100%;margin:0;padding:9px 12px;background:var(--soft);border-radius:8px;font-weight:500}
.menu{display:grid}.mi{display:flex;gap:12px;align-items:center;padding:13px 6px;border-bottom:1px solid var(--line);text-align:start}.mi.danger{color:var(--bad)}.mi:last-child{border-bottom:0}
.gres{margin-top:12px}.ask{position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:16px}.ask .box{position:relative;z-index:71;background:var(--panel);border-radius:12px;padding:20px;width:min(380px,100%)}.ask p{margin:0 0 14px;font-weight:500}
#toast{position:fixed;bottom:24px;inset-inline:0;margin:auto;width:fit-content;max-width:92vw;background:var(--ink);color:var(--bg);padding:9px 18px;border-radius:99px;opacity:0;pointer-events:none;transition:opacity .2s;z-index:80;text-align:center}#toast.on{opacity:1}
#print-area{display:none}.paper{color:#000;background:#fff;font-family:Tajawal,serif}.lh{display:flex;gap:14px;align-items:center;border-bottom:3px double #000;padding-bottom:10px;margin-bottom:20px}.lh img{width:56px;height:56px;border-radius:50%;object-fit:cover}.lh div{display:grid}.lh .lh-r{margin-inline-start:auto;text-align:end}.ph{text-align:center;margin:6px 0 16px}.pt{width:100%;border-collapse:collapse}.pt th,.pt td{border:1px solid #000;padding:7px 10px;text-align:start}.pt th{width:34%;background:#eee}.sig{margin-top:40px}.paper-body{line-height:2.1}
@media print{body.printing #shell,body.printing #sheet-root,body.printing #toast{display:none!important}body.printing #print-area{display:block}body{background:#fff}}
@media(max-width:820px){
 #shell{display:block}#rail{display:none}#view{padding:14px 14px 92px}
 #top{display:flex;align-items:center;gap:10px;position:sticky;top:0;z-index:5;background:var(--bg);padding:8px 14px;border-bottom:1px solid var(--line)}.tt{display:grid;line-height:1.25}.tt strong{font-size:16px}
 #tabs{display:grid;grid-template-columns:repeat(5,1fr);position:fixed;bottom:0;inset-inline:0;background:var(--panel);border-top:1px solid var(--line);z-index:10}
 #tabs button{display:grid;justify-items:center;gap:1px;padding:8px 2px 7px;font-size:10.5px;color:var(--muted);min-height:56px;text-align:center}#tabs button.cur{color:var(--a);font-weight:700}html[data-theme=dark] #tabs button.cur{color:var(--a2)}
 .card-id{padding:18px}.card-id h1{font-size:20px}.ledger b{font-size:18px}.ledger>div{padding:10px}
 .sheet,.sheet.wide{inset:auto 0 0 0;width:100%;max-height:92vh;border-radius:16px 16px 0 0}#toast{bottom:84px}.stats{grid-template-columns:repeat(3,1fr)}
}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}

.pickb{display:flex;align-items:center;justify-content:space-between;gap:8px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;min-height:44px;width:100%;text-align:start}.pickb .ic{width:18px;height:18px;flex:none;color:var(--muted)}.pickb span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pickb:focus-visible{outline:2px solid var(--a);outline-offset:1px}
.pk .box{max-height:min(86vh,640px);display:flex;flex-direction:column;gap:10px;padding:16px}.pk h3{margin:0;font-size:16px}.pl{list-style:none;margin:0;padding:0;overflow-y:auto;border:1px solid var(--line);border-radius:10px}
.pl li{display:flex;align-items:center;gap:2px;border-bottom:1px solid var(--line);padding-inline-end:4px}.pl li:last-child{border-bottom:0}.pl .none{padding:14px;color:var(--muted);justify-content:center}
.po{flex:1;display:flex;align-items:center;gap:12px;min-height:50px;padding:6px 12px;text-align:start}.po small{color:var(--muted)}
.rd{flex:none;width:22px;height:22px;border-radius:50%;border:2px solid var(--muted);display:grid;place-items:center}.rd.on{border-color:var(--a)}.rd.on::after{content:"";width:10px;height:10px;border-radius:50%;background:var(--a)}html[data-theme=dark] .rd.on{border-color:var(--a2)}html[data-theme=dark] .rd.on::after{background:var(--a2)}
.pl .dng:hover,.pl .dng:focus-visible{color:var(--bad)}.pl .ok{color:var(--ok)}.pl .lk{display:grid;place-items:center;width:38px;color:var(--muted);opacity:.6}.pl .lk .ic{width:16px;height:16px}
.pl li.ed{padding:6px}.pl li.ed input{flex:1;min-width:0;background:var(--panel);border:1px solid var(--a);border-radius:10px;padding:8px 12px;min-height:42px}
.padd{display:flex;gap:8px}.padd input{flex:1;min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 12px;min-height:44px}

.pl li.tn,.pl li.ed{padding-inline-start:calc(var(--lv,0)*18px)}.pl li.tn{position:relative}.pl li.tn[aria-level="2"]::before,.pl li.tn[aria-level="3"]::before,.pl li.tn[aria-level="4"]::before,.pl li.tn[aria-level="5"]::before{content:"";position:absolute;inset-block:0;inset-inline-start:calc(var(--lv,0)*18px - 9px);border-inline-start:1px dashed var(--line)}
.tg,.tg0{flex:none;width:30px;height:38px;display:grid;place-items:center}.tg .ic{width:16px;height:16px;color:var(--muted);transform:rotate(90deg);transition:transform .15s}.tg.o .ic{transform:rotate(0)}.tg:hover .ic,.tg:focus-visible .ic{color:var(--a)}
.po{min-width:0}.po span{overflow-wrap:anywhere}.underp{margin:0;padding:6px 10px;border-radius:10px;background:var(--panel);border:1px dashed var(--a);display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:13px}

.chipbar{display:grid;gap:6px}.chips.sub{padding-inline-start:calc(var(--lv,1)*14px);border-inline-start:2px solid var(--line);margin-inline-start:6px}.chip.path{border-color:var(--a)}.chip.quiet{border-style:dashed;color:var(--muted);display:inline-flex;align-items:center;gap:4px}.chip.quiet .ic{width:14px;height:14px}

